import { Component } from '@angular/core';
import { Modalidad } from '../../../models/modalidad.model';
import { ModalidadService } from '../../../controllers/modalidad.service';
import { ActivatedRoute, Router } from '@angular/router';
import { Form, GenericFormComponent } from "../../../shared/generic-form/generic-form.component";

const FORM_DEF:Form=[
  {
    key:'nombre',
    label:'Nombre de la Modalidad',
    type:'text',
    validator:{
      required:true
    },
    style:{
      div:'col p-3'
    }
  }
]

@Component({
    selector: 'app-form-modalidad',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-modalidad.component.html',
    styleUrl: './form-modalidad.component.css'
})
export class FormModalidadComponent {
  form=FORM_DEF
  modalidad?:Modalidad

  constructor(
    public modalidadController: ModalidadService,
    private route:ActivatedRoute,
    public router:Router,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params)=>{
      const id= params['modalidad_id']
      if(id){
        this.modalidad= await this.modalidadController.find(id)
      }
    })
  }
}
